                [value]="country.code"
                [checked]="selectedCode() === country.code"
                (change)="select(country.code)"
              />
              @if (country.iconUrl) {
                <img class="choice-tile__flag" [src]="country.iconUrl" alt="" />
              }
              <span class="choice-tile__name">{{ country.name }}</span>
              @if (selectedCode() === country.code) {
                <span class="choice-tile__selected">
                  <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
                    <path
                      d="M3 8.5l3.2 3.2L13 4.8"
                      fill="none"
                      stroke="currentColor"
                      stroke-width="2"
                      stroke-linecap="round"
                      stroke-linejoin="round"
                    />
                  </svg>
                  Seleccionado
                </span>
              }
            </label>
          }
        </fieldset>
        <button
          type="button"
          class="button button--cta"
          [disabled]="!canContinue()"
          (click)="continue()"
        >
          Continuar
        </button>
      }
    }
  }
</main>
