curl -s -g "http://localhost:1337/api/countries?fields[0]=code&fields[1]=legalAge"; echo; cat > "$TEMP/mw.js" <<'EOF'
(async () => {
  const ff = strapi.documents('api::form-field.form-field');
  const cl = await strapi.documents('api::country.country').findFirst({ filters: { code: 'CL' } });
  const co = await strapi.documents('api::country.country').findFirst({ filters: { code: 'CO' } });
  const base = { label: 'Prueba', type: 'text', required: false, errorMessage: 'x', order: 99, section: 'vehicle' };
  const run = async (name, fn) => { try { const r = await fn(); console.log('MW', name, 'OK', r && r.documentId ? 'created' : ''); return r; } catch (e) { console.log('MW', name, 'REJECTED:', e.message); } };
  await run('no-country', () => ff.create({ data: { ...base, key: 'testNoCountry' } }));
  await run('dup-key-CL', () => ff.create({ data: { ...base, key: 'plate', country: cl.documentId } }));
  const other = await run('new-key-CO', () => ff.create({ data: { ...base, key: 'testOnlyCo', country: co.documentId } }));
  const same = await run('same-key-other-country', () => ff.create({ data: { ...base, key: 'testOnlyCo', country: cl.documentId } }));
  if (other) await run('update-keeps-key', () => ff.update({ documentId: other.documentId, data: { label: 'Prueba 2' } }));
  if (other) await run('publish', () => ff.publish({ documentId: other.documentId }));
  if (other) await run('update-to-dup', () => ff.update({ documentId: other.documentId, data: { key: 'plate' } }));
  for (const d of [other, same]) if (d) await ff.delete({ documentId: d.documentId });
  console.log('MW done');
  process.exit(0);
})();
EOF
