  value: string;
}

export interface FormFieldDescriptor {
  key: string;
  label: string;
  type: FieldType;
  required: boolean;
  helpText: string | null;
  placeholder: string | null;
  errorMessage: string;
  order: number;
  section: FormSection;
  options: FieldOption[];
  rules: FieldRules;
}

export interface FormSections {
