        allowedCharacters: v.allowedCharacters ?? lim.allowedCharacters ?? null,
        maxLength: v.maxLength ?? lim.maxLength ?? null,
      };
      await app.documents(uid).update({ documentId: doc.documentId, data: { validations } });
      await app.documents(uid).publish({ documentId: doc.documentId });
