import { ChangeDetectionStrategy, Component, input } from '@angular/core';

@Component({
  selector: 'app-stepper',
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './stepper.component.scss',
  template: `
    <p class="stepper__summary">Paso {{ current() }} de {{ steps().length }}</p>
    <ol class="stepper">
      @for (step of steps(); track $index) {
        <li
          class="stepper__step"
          [class.stepper__step--current]="$index + 1 === current()"
          [class.stepper__step--done]="$index + 1 < current()"
          [attr.aria-current]="$index + 1 === current() ? 'step' : null"
        >
          <span class="stepper__circle">
            @if ($index + 1 < current()) {
              <svg
                class="stepper__check"
                viewBox="0 0 16 16"
                width="16"
                height="16"
                aria-hidden="true"
                focusable="false"
              >
                <path
                  d="M3 8.5l3.2 3.2L13 4.8"
                  fill="none"
                  stroke="currentColor"
                  stroke-width="2"
                  stroke-linecap="round"
                  stroke-linejoin="round"
                />
              </svg>
            } @else {
              <span aria-hidden="true">{{ $index + 1 }}</span>
            }
          </span>
          <span class="stepper__label"
            >{{ step }}@if ($index + 1 < current()) {
              <span class="visually-hidden"> (completado)</span>
            }</span
          >
        </li>
      }
    </ol>
  `,
})
export class StepperComponent {
  readonly steps = input.required<string[]>();
  readonly current = input<number>(1);
}
:host {
  display: block;
}

.stepper {
  display: flex;
  align-items: flex-start;
  list-style: none;
  margin: 0;
  padding: 0;

  &__summary {
    margin: 0 0 var(--space-2);
    font-size: 14px;
    font-weight: 500;
    color: var(--color-text-muted);

    @media (min-width: 576px) {
      position: absolute;
      width: 1px;
      height: 1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
      margin: 0;
    }
  }

  &__step {
    position: relative;
    flex: 1 1 0;
    display: none;
    flex-direction: column;
    align-items: center;
    gap: var(--space-2);
    text-align: center;
    color: var(--color-text-muted);

    &--current {
      display: flex;
    }

    @media (min-width: 576px) {
      display: flex;
    }

    &:not(:first-child)::before {
      content: '';
      position: absolute;
      top: 15px;
      right: calc(50% + 20px);
      left: calc(-50% + 20px);
      height: 2px;
      background: var(--color-border);
      display: none;

      @media (min-width: 576px) {
        display: block;
      }
    }

    &--done + &::before,
    &--done + &--current::before {
      background: var(--color-action);
    }
  }

  &__circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: var(--color-surface);
    box-shadow: inset 0 0 0 1.5px var(--color-border);
    color: var(--color-text-muted);
    font-size: 14px;
    font-weight: 700;
  }

  &__step--current &__circle,
  &__step--done &__circle {
    background: var(--color-surface-highlight);
    box-shadow: inset 0 0 0 2px var(--color-action);
    color: var(--color-brand);
  }

  &__label {
    font-size: 14px;
    font-weight: 500;
  }

  &__step--current &__label {
    font-weight: 700;
    color: var(--color-brand);
  }
}

